trait RouteControlMBean {
  def getStatus: String                    // attribute
  def suspend(reason: String): Unit        // command
  def resume(): Unit
}

class RouteControl(route: Route) extends RouteControlMBean {
  override def getStatus: String = route.state.toString
  override def suspend(reason: String): Unit = route.suspend(reason)
  override def resume(): Unit = route.resume()
}

ManagementFactory.getPlatformMBeanServer.registerMBean(
  new StandardMBean(new RouteControl(route), classOf[RouteControlMBean]),
  new ObjectName("app.routes:type=Route,name=orders"))
